import{_ as m,a0 as l,w as p,s as n,ao as i,I as a,x as e,a1 as r,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"Mattermost 7.0 發佈，擴展了工作流平台 | LCTT x X-CMD","titleTemplate":false,"description":"Mattermost 7.0 發佈，擴展了工作流平台 | LCTT (202206) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Mattermost 7.0 發佈，擴展了工作流平台 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Mattermost 7.0 發佈，擴展了工作流平台 | LCTT (202206) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202206/20220616 Mattermost Extends workflow platform with 7.0 release","title":"Mattermost 7.0 發佈，擴展了工作流平台","tag":"202206","desc":""},"relativePath":"202206/20220616 Mattermost Extends workflow platform with 7.0 release.md","filePath":"[post].md"}'),f={name:"202206/20220616 Mattermost Extends workflow platform with 7.0 release.md"};function d(u,t,w,T,M,x){const o=l("Link");return p(),n("div",null,[t[15]||(t[15]=i('<h1 id="mattermost-7-0-發佈-擴展了工作流平台" tabindex="-1">Mattermost 7.0 發佈，擴展了工作流平台 <a class="header-anchor" href="#mattermost-7-0-發佈-擴展了工作流平台" aria-label="Permalink to “Mattermost 7.0 發佈，擴展了工作流平台”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/06/marttermost-e1655377462300.jpeg" alt="Mattermost"></p><p>自 2016 年開源以來，Mattermost 一直在開發一個具有不斷增加的用例的消息傳遞平台。6 月 16 日，Mattermost 7.0 平台發佈，其中包括了新的語音呼叫、工作流模板和用於開源技術的應用框架。新版本擴展了 2021 年 10 月發佈的 6.0 版本引入的功能。一直以來，Mattermost 都在與包括 Slack、Atlassian 和 Asana 在內的幾家大公司，競爭不斷增長的協作工具市場。另一方面，Mattermost 側重於對開發者的支持，儘管該平台也可用於安全和 IT 運營。</p><p>Mattermost 的軟件同時提供有商業版和開源版，目前它們都升級到了 7.0 版。Tien 解釋説，Mattermost 的商業平台是建立在開源基礎上的。在開放核心模型中，開源版作為軟件的基礎或核心，專有的企業功能則內置於商業版中。合規性、規模性和高級配置是 Mattermost 的關鍵企業功能。Tien 聲稱，開源版本對於中小型團隊來説已經足夠了。他認為，擁有 500 名或更多用户的團隊才需要考慮使用商業版。</p><p>Tien 認為開源也關乎社區貢獻。Mattermost 開源項目有超過 4000 名個人貢獻者，他們貢獻了超過 30000 行代碼。</p><p>以前，Mattermost 依賴集成第三方呼叫服務（例如 Zoom）來啓用語音呼叫功能。在 7.0 版本中，它通過開源 WebRTC 協議引入了呼叫功能的直接集成，所有現代 Web 瀏覽器都支持該協議。直接集成呼叫功能的目標是為協作提供單一平台，這符合 Tien 對該平台的總體願景。現在，除了提供集成工具以實現協作之外，該平台還會增加“工作流模板”功能，以幫助（用户）組織構建可重複的流程。</p><p>工作流概念採用了 <ruby>劇本<rt>playbook</rt></ruby>，其中包含了為“特定類型的操作”所執行的動作和操作的清單。例如，在發生服務故障或網絡安全事件時，公司可以為事件響應創建工作流模板。</p><p>這個清單可以鏈接到 Mattermost <ruby>操作<rt>operation</rt></ruby>，例如讓特定用户發起呼叫，並協助生成報告。Tien 表示，Mattermost 還與常見的開發者工具集成，並且工作流模板的功能將隨着時間的推移而擴展，以便使用第三方工具來實現更多自動化。</p><hr>',9)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/06/mattermost-extends-workflow-platform-with-7-0-release/"},{default:s(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/06/mattermost-extends-workflow-platform-with-7-0-release/",-1)])]),_:1})]),a("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:s(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(o,{href:"https://github.com/lkxed"},{default:s(()=>[...t[4]||(t[4]=[e("lkxed",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:s(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:s(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const g=m(f,[["render",d]]);export{b as __pageData,g as default};
